package com.bank.guarantee.producer;

import com.bank.guarantee.model.TransferEvent;
import java.util.logging.*;

// acks=all + min.insync + retries: keep trying until all in-sync replicas persist.
public class GuaranteedProducer {
    private static final Logger log = Logger.getLogger(GuaranteedProducer.class.getName());

    private final int minInsync;
    private final int maxRetries;

    public GuaranteedProducer(int minInsync, int maxRetries) {
        this.minInsync = minInsync; this.maxRetries = maxRetries;
    }

    // Simulate ISR fluctuating: returns true (acked) once ISR>=minInsync on some attempt.
    public boolean send(TransferEvent e, int[] isrPerAttempt) {
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            int isr = attempt < isrPerAttempt.length ? isrPerAttempt[attempt] : minInsync;
            if (isr >= minInsync) {
                log.info(() -> "Produced " + e + " acked (ISR " + isr + " >= " + minInsync + ")");
                return true;
            }
            log.warning("Produce attempt " + attempt + " for " + e.getId()
                + " rejected (ISR " + isr + " < " + minInsync + "), retrying...");
        }
        log.severe("Delivery timeout exhausted for " + e.getId());
        return false;
    }
}
