package com.bank.guarantee.consumer;

import com.bank.guarantee.dlq.DeadLetterQueue;
import com.bank.guarantee.model.TransferEvent;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

// Manual commit after processing; bounded retry; DLQ for permanent failures; idempotent.
public class GuaranteedConsumer {
    private static final Logger log = Logger.getLogger(GuaranteedConsumer.class.getName());
    private static final int MAX_ATTEMPTS = 3;

    private final DeadLetterQueue dlq;
    private final Set<String> processedIds = new HashSet<>(); // idempotency
    private long committedOffset = -1;

    public GuaranteedConsumer(DeadLetterQueue dlq) { this.dlq = dlq; }

    public void onRecord(long offset, TransferEvent e) {
        if (processedIds.contains(e.getId())) {
            log.warning("Duplicate " + e.getId() + " skipped (idempotent)");
            committedOffset = offset; // still advance
            return;
        }
        for (int attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            try {
                process(e);
                processedIds.add(e.getId());
                committedOffset = offset;    // commit ONLY after success
                log.info(() -> "Processed " + e + ", committed offset=" + committedOffset);
                return;
            } catch (RuntimeException ex) {
                if (e.isPermanentlyBad()) {
                    dlq.publish(e, "permanent: " + ex.getMessage());
                    committedOffset = offset; // advance past DLQ'd record
                    log.severe("Permanent failure " + e.getId() + " -> DLQ, committed " + offset);
                    return;
                }
                if (attempt == MAX_ATTEMPTS) {
                    dlq.publish(e, "retries exhausted: " + ex.getMessage());
                    committedOffset = offset;
                    log.severe("Retries exhausted " + e.getId() + " -> DLQ, committed " + offset);
                    return;
                }
                log.warning("Transient failure " + e.getId() + " attempt " + attempt + ", retry");
            }
        }
    }

    private void process(TransferEvent e) {
        if (e.isPermanentlyBad() || e.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("invalid transfer " + e.getId());
        }
        // real settlement (debit/credit) would happen here
    }

    public long getCommittedOffset() { return committedOffset; }
}
