package com.bank.guarantee;

import com.bank.guarantee.consumer.GuaranteedConsumer;
import com.bank.guarantee.dlq.DeadLetterQueue;
import com.bank.guarantee.model.TransferEvent;
import com.bank.guarantee.producer.GuaranteedProducer;
import java.math.BigDecimal;
import java.util.logging.*;

public class GuaranteeDemo {
    private static final Logger log = Logger.getLogger(GuaranteeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // PRODUCER: ISR dips below 2 for first two attempts, recovers on third.
        GuaranteedProducer producer = new GuaranteedProducer(2, 5);
        TransferEvent t1 = new TransferEvent("T1", "SAV2001", "CUR3001", new BigDecimal("50000"), false);
        producer.send(t1, new int[]{1, 1, 3});

        // CONSUMER: good record committed on success; bad record dead-lettered.
        DeadLetterQueue dlq = new DeadLetterQueue();
        GuaranteedConsumer consumer = new GuaranteedConsumer(dlq);
        consumer.onRecord(100, t1);
        consumer.onRecord(101, t1); // duplicate -> idempotent skip
        consumer.onRecord(102, new TransferEvent("T2", "CUR3001", "SAV2001",
            new BigDecimal("20000"), true)); // permanently bad -> DLQ

        log.info("Final committed offset=" + consumer.getCommittedOffset());
        log.info("DLQ: " + dlq.getEntries());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
